    goals = {'A': [2, 3]}
    action_budget = 8

    def is_valid_move(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != '#'

    def get_neighbors(x, y):
        return [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]

    def get_successors(agents):
        successors = []
        for dx, dy in get_neighbors(agents['A'][0], agents['A'][1]):
            x, y = agents['A'][0] + dx, agents['A'][1] + dy
            if is_valid_move(x, y) and (x, y) not in agents.values():
                successors.append((x, y))
        return successors

    def backtrack(agents, path):
        if all(agent == goals[agent] for agent in agents):
            return [{'agent': 'A', 'move': 'R'}]

        if len(path) > action_budget:
            return None

        successors = get_successors(agents)
        new_agents = {}

        for x, y in path:
            if (x, y) not in agents.values():
                for dx, dy in get_neighbors(x, y):
                    new_x, new_y = x + dx, y + dy
                    if is_valid_move(new_x, new_y) and grid[new_x][new_y] != '#':
                        new_agents[(x, y)] = {'agent': 'L', 'move': 'D'}

        for agent, move in path:
            if (agent, move) not in agents.values():
                for dx, dy in get_neighbors(agent[0], agent[1]):
                    new_x, new_y = agent[0] + dx, agent[1] + dy
                    if is_valid_move(new_x, new_y):
                        new_agents[(new_x, new_y)] = {'agent': 'R', 'move': 'U'}

        result = []
        for x, y in path:
            if (x, y) not in agents.values():
                for dx, dy in get_neighbors(x, y):
                    new_x, new_y = x + dx, y + dy
                    if is_valid_move(new_x, new_y) and grid[new_x][new_y] != '#':
                        result.append({'agent': 'U', 'move': 'D'})

        for (x, y), agent in agents.items():
            if (x, y) not in agents.values() and not agent['agent'] == 'L' and not agent['agent'] == 'R':
                new_x, new_y = x + dx, y + dy
                if is_valid_move(new_x, new_y):
                    result.append({'agent': 'D', 'move': 'U'})

        return agents.copy() + list(itertools.chain.from_iterable(result))

    path = []
    current Agents = get_agents()
    while True:
        new_path = backtrack(current_agents, path)
        if new_path is None:
            break
        path = new_path

    return path

def get_agents():
    return {'A': [2, 1]}

def main():
    grid = [['#', '#', '#', '#'],
           ['#', 'U', '.', '.'],
           ['.', '.', '.', '.'],
           ['.','.','.','.']]

    result = laberinto(grid)
    print(result)

main()
