import random
import json

def generar_grid(grid_size):
    return [['#' for _ in range(6)] + ['.' for _ in range(7)] + ['#']]

def crear_agent(grd, fila, columna):
    agent = {'grid': grd, 'fila': fila, 'columna': columna}
    return agent

def mover_agente(grid, agent, fila, columna, movimiento):
    if 0 <= fila < len(grid) and 0 <= columna < len(grid[0]):
        new_grid = []
        for i in range(len(grid)):
            row = ''
            for j in range(len(grid[0])):
                if (i, j) == (agent['fila'], agent['columna']):
                    row += 'K'
                elif grid[i][j] == '#':
                    row += '.'
                else:
                    row += grid[i][j]
            new_grid.append(row)
        return {'grid': new_grid, 'fila': fila + 1}
    else:
        return {}

def resolver_laberinto(grid_size):
    agent = crear_agent(generar_grid(grid_size), 0, 0)
