        for movimiento in ['U', 'D', 'L', 'R']:
            new_grid = mover_agente(agent['grid'], agent, agent['fila'], agent['columna'], movimiento)
            if new_grid:
                acciones.append({'agent': 'A', 'move': movimiento})
                agent = new_grid
        grid_size -= 1
        if not grid_size:
            return acciones

def guardar_soluciones(soluciones):
    with open('soluciones.json', 'w') as f:
