agent = {"pos": [0, 0], "suelo": True, "llave": False}

def move_agent(grid, agent):
    acciones = {
        'U': [-1, 0],
        'D': [1, 0],
        'L': [0, -1],
        'R': [0, 1]
    }
    random.shuffle(aciones) # Simular la acción aleatoria
    for a in acciones:
        n_x, n_y = agent["pos"][0] + a[0], agent["pos"][1] + a[1]
        if (n_x < 0 or n_x >= len(grid)) or (n_y < 0 or n_y >= len(grid[0])) or grid[n_x][n_y] == '#':
            return None
        elif not grid[n_x][n_y]:
            agent["pos"] = [n_x, n_y]
            if a == 'R' and grid[n_x][n_y + 1] != '#' and grid[n_x][n_y + 1].get("llave", False):
                agent["suelo"] = True
                agent["llave"] = True
            elif a == 'L':
                agent["pos"][1] *= -1 if n_x > 0 else 1
        else:
            return None

def print_grid(grid, agent):
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if [i, j] == agent["pos"]:
                print("A", end=" ")
            elif grid[i][j] != '#':
                print(grid[i][j], end=" ")
        print()

def solve_laberinto(grid):
    global agent
    while True:
        for a in ["U", "D", "L", "R"]:
            if move_agent(grid, {"pos": [0, 0], "suelo": True, "llave": False}):
                grid[agent["pos"][0]][agent["pos"][1]] = "."
                agent["pos"] = [0, 0]
        for a in ["U", "D", "L", "R"]:
            if move_agent(grid, {"pos": [agent["pos"][0], agent["pos"][1]], "suelo": True, "llave": False}):
                grid[agent["pos"][0]][agent["pos"][1]] = "."
                agent["pos"] = [0, 0]
        if (grid[3][4] == "." and grid[2][5] == "." and grid[1][6] == "." and
            grid[0][7] == "." and grid[-1][-1] == "."):
            break

# Inicializar el laberinto y los agentes
