            else:
                grid[i][4] = "#"

    return grid, objetos

def mover_agent(grid, objetos, agente):
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (i, j) != (agente[1], agente[0]):
                if grid[i][j] == "k":
                    # Agregar la llave al inventario compartido
                    objetos.append("llave")
                elif grid[i][j] == "D":
                    # Abrir la puerta y avanzar hacia la siguiente casilla
                    for k in range(i + 1, len(grid)):
                        if (k, i) != (agente[1], agente[0]):
                            grid[k][i] = "."
                            break
                elif grid[i][j] == "p":
                    # Movimiento del agente hasta la siguiente casilla que sea accesible
                    for k in range(i + 1, len(grid)):
                        if (k, i) != (agente[1], agente[0]):
                            grid[k][i] = "."
                            break

def completar_objetivos(grid, objetos):
    for i in range(len(grid)):
        for j in range(len(grid[0])):
