  return obj['goals']['A'][0] === 1 && obj['grid'][obj['agents']['A'][1]][obj['agents']['A'][0]] === 'D';
}

function isValidMove(grid, agent, move) {
  const row = agent[1];
  const col = agent[0];

  if (move === 'U') {
    return grid[row + 1][col] !== '#';
  } else if (move === 'D') {
    return grid[row][col + 1] !== '#';
  } else if (move === 'L') {
    return grid[row - 1][col] !== '#' && grid[row][col - 1] !== '.';
  } else if (move === 'R') {
    return grid[row + 1][col] !== '.' && grid[row][col + 1] !== '#';
  }
}

function updateGrid(grid, agent, move) {
  const row = agent[1];
  const col = agent[0];

  switch (move) {
    case 'U':
      grid[row - 1][col] = '.';
      break;
    case 'D':
      grid[row + 1][col] = '.';
      break;
    case 'L':
      grid[row][col - 1] = '.';
      break;
    case 'R':
      grid[row][col + 1] = '.';
      break;
  }
}

function backtrack(grid, agents) {
  const obj = {grid: grid, agents: agents};
  if (checkGoal(obj)) {
    return JSON.stringify([{'agent': 'A', 'move': 'R'}]);
  }

